"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { supabase } from "@/lib/supabase";
import { Loader2, Coins } from "lucide-react";
import { ACCOUNT_PROFILE_SELECT } from "@/lib/accountProfileFields";
import { getOnboardingHubRedirect } from "@/lib/onboardingState";
import { checkSlugAvailability, normalizeSlug } from "@/lib/slugAvailability";
import { getMissingOnboardingFields } from "@/lib/onboardingChecklist";
import GooglePlacesAutocomplete from "@/components/address/GooglePlacesAutocomplete";
import ManualAddressFields from "@/components/address/ManualAddressFields";
import { getGoogleMapsBrowserKey } from "@/lib/googlePlacesParsed";
import type { ParsedGooglePlace } from "@/lib/googlePlacesParsed";

type ProfileRow = {
  email: string | null;
  display_name: string | null;
  full_name: string | null;
  bio: string | null;
  phone_number: string | null;
  location_state: string | null;
  location_city: string | null;
  location: string | null;
  currency_code: string | null;
  slug: string | null;
  logo_url: string | null;
  coin_balance: number | null;
  is_seller: boolean | null;
  is_verified: boolean | null;
  verification_status: string | null;
  onboarding_completed: boolean | null;
  onboarding_step: string | null;
  discovery_city: string | null;
  discovery_state: string | null;
  discovery_latitude: number | null;
  discovery_longitude: number | null;
  service_latitude: number | null;
  service_longitude: number | null;
  location_country: string | null;
  location_country_code: string | null;
};

function headlineName(p: ProfileRow | null, emailFallback: string) {
  return p?.full_name?.trim() || p?.display_name?.trim() || emailFallback.split("@")[0] || "Your profile";
}

export default function AccountProfilePage() {
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [authEmail, setAuthEmail] = useState("");
  const [profile, setProfile] = useState<ProfileRow | null>(null);
  const [fullName, setFullName] = useState("");
  const [bio, setBio] = useState("");
  const [phone, setPhone] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [locationState, setLocationState] = useState("");
  const [locationCity, setLocationCity] = useState("");
  const [homeAddress, setHomeAddress] = useState("");
  const [slug, setSlug] = useState("");
  const [slugStatus, setSlugStatus] = useState<"idle" | "checking" | "available" | "taken">("idle");
  const [storeAddress, setStoreAddress] = useState("");
  const [homeLat, setHomeLat] = useState<number | null>(null);
  const [homeLng, setHomeLng] = useState<number | null>(null);
  const [shopLat, setShopLat] = useState<number | null>(null);
  const [shopLng, setShopLng] = useState<number | null>(null);
  const [homeCountryName, setHomeCountryName] = useState("");
  const [homeCountryCode, setHomeCountryCode] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [nextSetupPath, setNextSetupPath] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      setAuthEmail(user.email || "");

      const { data, error } = await supabase
        .from("profiles")
        .select(ACCOUNT_PROFILE_SELECT)
        .eq("id", user.id)
        .maybeSingle();

      if (error) {
        setLoadError(error.message);
        setLoading(false);
        return;
      }

      const p = data as ProfileRow | null;
      setProfile(p);
      setFullName(p?.full_name?.trim() || p?.display_name?.trim() || "");
      setBio(p?.bio || "");
      setPhone(p?.phone_number || "");
      setLogoUrl(p?.logo_url?.trim() || "");
      setLocationState(p?.location_state || "");
      setLocationCity(p?.location_city || "");
      setHomeAddress(p?.location || "");
      setHomeLat(p?.discovery_latitude != null ? Number(p.discovery_latitude) : null);
      setHomeLng(p?.discovery_longitude != null ? Number(p.discovery_longitude) : null);
      setShopLat(p?.service_latitude != null ? Number(p.service_latitude) : null);
      setShopLng(p?.service_longitude != null ? Number(p.service_longitude) : null);
      setSlug(p?.slug || "");

      if (p?.is_seller) {
        const { data: sellerStore } = await supabase
          .from("stores")
          .select("slug, location")
          .eq("owner_id", user.id)
          .maybeSingle();
        setStoreAddress(sellerStore?.location?.trim() ? String(sellerStore.location) : "");
        const path = getOnboardingHubRedirect({ profile: p as any, hasStore: !!sellerStore });
        setNextSetupPath(path.startsWith("/onboarding") ? path : null);
      } else {
        const path = getOnboardingHubRedirect({ profile: p as any, hasStore: false });
        setNextSetupPath(path.startsWith("/onboarding") ? path : null);
      }
      setLoading(false);
    })();
  }, []);

  useEffect(() => {
    const timer = setTimeout(async () => {
      const trimmed = normalizeSlug(slug);
      const currentSlug = normalizeSlug(profile?.slug || "");
      if (!trimmed) {
        setSlugStatus("idle");
        return;
      }
      if (trimmed === currentSlug) {
        setSlugStatus("available");
        return;
      }
      setSlugStatus("checking");
      const {
        data: { user },
      } = await supabase.auth.getUser();
      const status = await checkSlugAvailability(supabase, trimmed, user?.id || null);
      setSlugStatus(status);
    }, 350);

    return () => clearTimeout(timer);
  }, [slug, profile?.slug]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setMsg(null);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      const trimmedLogo = logoUrl.trim();
      const fn = fullName.trim() || null;

      const profilePatch: Record<string, unknown> = {
        display_name: fn,
        full_name: fn,
        bio: bio.trim() || null,
        phone_number: phone.trim() || null,
        logo_url: trimmedLogo || null,
        slug: normalizeSlug(slug) || null,
        location_state: locationState.trim() || null,
        location_city: locationCity.trim() || null,
        location: homeAddress.trim() || null,
        discovery_city: locationCity.trim() || null,
        discovery_state: locationState.trim() || null,
        discovery_latitude: homeLat,
        discovery_longitude: homeLng,
        location_country: homeCountryName.trim() || null,
        location_country_code: homeCountryCode.trim().toUpperCase() || null,
        updated_at: new Date().toISOString(),
      };

      if (profile?.is_seller) {
        profilePatch.service_latitude = shopLat;
        profilePatch.service_longitude = shopLng;
      }

      const { error } = await supabase.from("profiles").update(profilePatch).eq("id", user.id);

      if (error) throw error;

      if (profile?.is_seller && (normalizeSlug(slug) || storeAddress.trim())) {
        const { error: storeError } = await supabase
          .from("stores")
          .update({
            slug: normalizeSlug(slug) || null,
            location: storeAddress.trim() || null,
          })
          .eq("owner_id", user.id);
        if (storeError) throw storeError;
      }

      setProfile((prev) =>
        prev
          ? {
              ...prev,
              display_name: fn,
              full_name: fn,
              bio: bio.trim() || null,
              phone_number: phone.trim() || null,
              logo_url: trimmedLogo || null,
              slug: normalizeSlug(slug) || null,
              location_state: locationState.trim() || null,
              location_city: locationCity.trim() || null,
              location: homeAddress.trim() || null,
              discovery_latitude: homeLat,
              discovery_longitude: homeLng,
              location_country: homeCountryName.trim() || null,
              location_country_code: homeCountryCode.trim().toUpperCase() || null,
              service_latitude: profile?.is_seller ? shopLat : prev.service_latitude,
              service_longitude: profile?.is_seller ? shopLng : prev.service_longitude,
            }
          : prev,
      );
      setMsg("Saved.");
    } catch (err: unknown) {
      setMsg(err instanceof Error ? err.message : "Could not save.");
    } finally {
      setSaving(false);
    }
  };

  const handleLogoUpload = async (file: File | null) => {
    if (!file) return;
    setUploadingLogo(true);
    setMsg(null);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;
      const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
      const path = `profiles/${user.id}/logo_${Date.now()}.${ext}`;
      const { error: uploadError } = await supabase.storage.from("products").upload(path, file, {
        upsert: true,
        contentType: file.type || "image/jpeg",
      });
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from("products").getPublicUrl(path);
      setLogoUrl(data.publicUrl);
      setMsg("Logo uploaded. Click Save profile to persist.");
    } catch (err: unknown) {
      setMsg(err instanceof Error ? err.message : "Logo upload failed.");
    } finally {
      setUploadingLogo(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="animate-spin text-emerald-600" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="rounded-2xl border border-red-100 bg-red-50 p-6 text-sm text-red-900 font-medium">
        Could not load profile: {loadError}
      </div>
    );
  }

  const emailShown = profile?.email?.trim() || authEmail || "—";
  const currentProfileSlug = profile?.slug?.trim();
  const showAvatar = logoUrl.trim() || profile?.logo_url;
  const mapsKey = getGoogleMapsBrowserKey();

  const missingSetup = getMissingOnboardingFields(
    {
      full_name: fullName,
      phone_number: phone,
      slug: normalizeSlug(slug),
      location_state: locationState,
      location_city: locationCity,
      location: homeAddress,
      service_latitude: shopLat,
      service_longitude: shopLng,
    },
    Boolean(profile?.is_seller),
    {
      slug: normalizeSlug(slug),
      location: storeAddress,
    }
  );

  return (
    <div className="max-w-2xl space-y-8" id="personal-information">
      <div>
        <h1 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">PERSONAL INFORMATION</h1>
        <p className="text-gray-500 text-sm font-medium mt-1">
          Name, bio, username, and contact details used across StoreLink.
        </p>
      </div>
      {nextSetupPath && (
        <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4 flex items-center justify-between gap-3">
          <div>
            <p className="text-[10px] font-black uppercase tracking-widest text-emerald-700">Setup incomplete</p>
            <p className="text-xs font-medium text-emerald-900 mt-1">
              Finish setup to keep app and web fully in sync.
            </p>
          </div>
          <Link href={nextSetupPath} className="px-4 py-2 rounded-xl bg-emerald-600 text-white text-[10px] font-black uppercase tracking-widest">
            Continue setup
          </Link>
        </div>
      )}
      {missingSetup.length > 0 && (
        <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4">
          <p className="text-[10px] font-black uppercase tracking-widest text-amber-700">Missing setup fields</p>
          <p className="text-xs text-amber-900 font-medium mt-1">
            Complete these fields to finish setup.
          </p>
          <p className="text-xs text-amber-800 mt-2 font-bold">{missingSetup.join(" · ")}</p>
        </div>
      )}

      {/* Identity summary — matches profile row used across StoreLink */}
      <div className="rounded-4xl border border-gray-100 bg-white shadow-sm overflow-hidden">
        <div className="h-14 bg-linear-to-r from-gray-100 to-gray-50" />
        <div className="p-6 flex flex-col sm:flex-row gap-6 sm:items-end">
          <div className="-mt-14 sm:-mt-16 relative shrink-0">
            <div className="w-28 h-28 rounded-3xl overflow-hidden bg-gray-100 border-4 border-white shadow-md flex items-center justify-center">
              {showAvatar ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={(logoUrl.trim() || profile?.logo_url) as string} alt="" className="w-full h-full object-cover" />
              ) : (
                <span className="text-4xl font-black text-gray-300 uppercase">{headlineName(profile, authEmail).slice(0, 1)}</span>
              )}
            </div>
          </div>
          <div className="flex-1 min-w-0 pb-1">
            <p className="text-xl font-black text-gray-900 tracking-tight">{headlineName(profile, authEmail)}</p>
            <div className="mt-3 space-y-1.5 text-sm">
              <p className="text-gray-700 font-medium">
                <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block">Username</span>
                {currentProfileSlug ? (
                  <span className="font-mono text-emerald-800 font-bold">@{currentProfileSlug}</span>
                ) : (
                  <span className="text-gray-400 font-medium">No username on file yet.</span>
                )}
              </p>
              <p className="text-gray-700 font-medium">
                <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block">Email</span>
                {emailShown}
              </p>
              {profile?.is_seller &&
                profile?.verification_status &&
                profile.verification_status !== "none" && (
                  <p className="text-xs text-gray-600 font-medium">
                    {profile.verification_status === "verified" && (
                      <span className="text-emerald-800 font-bold">Seller ID verified</span>
                    )}
                    {profile.verification_status === "pending" && (
                      <span>ID verification pending — finish in your seller dashboard when ready.</span>
                    )}
                    {profile.verification_status === "rejected" && (
                      <span className="text-red-700 font-bold">ID verification needs attention</span>
                    )}
                  </p>
                )}
            </div>
            <Link
              href="/account/wallet"
              className="inline-flex items-center gap-2 mt-4 text-emerald-700 font-black text-[10px] uppercase tracking-widest hover:underline"
            >
              <Coins size={14} /> Wallet &amp; Store Coins
            </Link>
          </div>
        </div>
      </div>

      <form onSubmit={handleSave} className="space-y-5 bg-white rounded-4xl border border-gray-100 p-8 shadow-sm">
        <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">EDIT PERSONAL INFORMATION</p>

        <div className="grid gap-5 sm:grid-cols-2">
          <div className="sm:col-span-2 rounded-2xl border border-gray-100 bg-gray-50/80 p-5 flex flex-col sm:flex-row gap-5 sm:items-center">
            <div className="w-24 h-24 rounded-2xl overflow-hidden bg-white border border-gray-100 shrink-0 flex items-center justify-center">
              {logoUrl.trim() ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={logoUrl.trim()} alt="" className="w-full h-full object-cover" />
              ) : (
                <span className="text-2xl font-black text-gray-300">{headlineName(profile, authEmail).slice(0, 1)}</span>
              )}
            </div>
            <div className="flex-1 min-w-0 space-y-3">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Profile photo</label>
                <label className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-900 text-white text-[10px] font-black uppercase tracking-widest cursor-pointer">
                  {uploadingLogo ? "Uploading..." : "Upload image"}
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    disabled={uploadingLogo}
                    onChange={(e) => void handleLogoUpload(e.target.files?.[0] || null)}
                  />
                </label>
                <p className="text-[11px] text-gray-500 mt-2 font-medium">Shown on your profile and storefront.</p>
              </div>
            </div>
          </div>
          <div className="sm:col-span-2">
            <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Username</label>
            <input
              className="w-full p-4 rounded-2xl bg-gray-50 border border-gray-100 font-bold text-gray-900 text-sm outline-none focus:ring-2 focus:ring-gray-900"
              value={slug}
              onChange={(e) => setSlug(e.target.value)}
              placeholder="your-name"
            />
            {slug && (
              <p className={`text-[11px] mt-2 font-bold ${slugStatus === "taken" ? "text-red-600" : "text-gray-500"}`}>
                {slugStatus === "checking" && "Checking availability..."}
                {slugStatus === "available" && `Available: @${normalizeSlug(slug)}`}
                {slugStatus === "taken" && "Slug is already in use."}
              </p>
            )}
          </div>
          <div className="sm:col-span-2">
            <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Full name</label>
            <input
              className="w-full p-4 rounded-2xl bg-gray-50 border border-gray-100 font-bold text-gray-900 text-sm outline-none focus:ring-2 focus:ring-gray-900"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              placeholder="Legal / shipping name"
            />
          </div>
          <div className="sm:col-span-2">
            <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Bio</label>
            <textarea
              rows={3}
              className="w-full p-4 rounded-2xl bg-gray-50 border border-gray-100 font-medium text-gray-900 text-sm outline-none focus:ring-2 focus:ring-gray-900 resize-none"
              value={bio}
              onChange={(e) => setBio(e.target.value)}
              placeholder="Short intro shown on your profile"
            />
          </div>
          <div className="sm:col-span-2">
            <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Phone</label>
            <input
              className="w-full p-4 rounded-2xl bg-gray-50 border border-gray-100 font-bold text-gray-900 text-sm outline-none focus:ring-2 focus:ring-gray-900"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="+234…"
            />
          </div>

          <div className="sm:col-span-2 rounded-3xl border border-emerald-100 bg-emerald-50/30 p-5 md:p-6 space-y-4">
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-800">Home location</p>
              <p className="text-[11px] text-gray-600 font-medium mt-1 leading-relaxed">
                Same field as onboarding “home” — used across StoreLink. Order checkout can still use a different delivery address when you buy.
              </p>
            </div>
            {mapsKey ? (
              <GooglePlacesAutocomplete
                id="profile-home-address"
                label="Search and select your home address"
                hint="Choose a suggestion to align city, region, and map pin with the mobile app."
                value={homeAddress}
                onChangeText={setHomeAddress}
                onResolved={(p: ParsedGooglePlace) => {
                  setHomeLat(p.lat);
                  setHomeLng(p.lng);
                  if (p.city) setLocationCity(p.city);
                  if (p.state) setLocationState(p.state);
                  if (p.country) setHomeCountryName(p.country);
                  if (p.countryCode) setHomeCountryCode(p.countryCode);
                }}
                countryBias="ng"
              />
            ) : (
              <p className="text-[11px] font-semibold text-amber-900 bg-amber-50 border border-amber-100 rounded-xl p-3 leading-relaxed">
                Set <span className="font-mono text-[10px]">NEXT_PUBLIC_GOOGLE_MAPS_API_KEY</span> in your environment for Google address search. You can still edit manually below.
              </p>
            )}
            <ManualAddressFields
              locationState={locationState}
              locationCity={locationCity}
              addressLine={homeAddress}
              onState={setLocationState}
              onCity={setLocationCity}
              onAddress={setHomeAddress}
              addressLabel="Street address & details"
            />
            {(homeLat != null || homeLng != null) && (
              <p className="text-[10px] font-mono text-gray-400">
                Saved pin: {homeLat?.toFixed(5)}, {homeLng?.toFixed(5)}
              </p>
            )}
          </div>

          {profile?.is_seller && (
            <div className="sm:col-span-2 rounded-3xl border border-gray-200 bg-gray-50/50 p-5 md:p-6 space-y-4">
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-gray-500">Shop / business location</p>
                <p className="text-[11px] text-gray-600 font-medium mt-1 leading-relaxed">
                  Where buyers find your storefront — stored as coordinates on your profile (same as the app shop location).
                </p>
              </div>
              {mapsKey ? (
                <GooglePlacesAutocomplete
                  id="profile-shop-address"
                  label="Search shop, studio, or pickup point"
                  hint="Separate from your home address above."
                  value={storeAddress}
                  onChangeText={setStoreAddress}
                  onResolved={(p: ParsedGooglePlace) => {
                    setShopLat(p.lat);
                    setShopLng(p.lng);
                  }}
                  countryBias="ng"
                />
              ) : (
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">
                    Shop address (manual)
                  </label>
                  <textarea
                    rows={2}
                    className="w-full p-4 rounded-2xl bg-white border border-gray-100 font-medium text-gray-900 text-sm outline-none focus:ring-2 focus:ring-gray-900 resize-none"
                    value={storeAddress}
                    onChange={(e) => setStoreAddress(e.target.value)}
                    placeholder="Where you work or customers pick up"
                  />
                </div>
              )}
              {(shopLat != null || shopLng != null) && (
                <p className="text-[10px] font-mono text-gray-400">
                  Shop pin: {shopLat?.toFixed(5)}, {shopLng?.toFixed(5)}
                </p>
              )}
              <div className="rounded-2xl bg-white border border-gray-100 p-4">
                <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">Store slug</p>
                <p className="font-mono text-sm font-bold text-gray-900">{normalizeSlug(slug) || "—"}</p>
                <p className="text-[11px] text-gray-500 mt-2 font-medium">Public URL uses this handle — same as your username above.</p>
              </div>
            </div>
          )}
        </div>

        <div className="rounded-2xl bg-gray-50 border border-gray-100 p-4 text-sm">
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">STORE COINS</p>
          <p className="font-black text-gray-900 text-lg">{Number(profile?.coin_balance ?? 0).toLocaleString()}</p>
        </div>

        {msg && <p className="text-xs font-bold text-emerald-700">{msg}</p>}

        <button
          type="submit"
          disabled={saving || slugStatus === "taken" || slugStatus === "checking"}
          className="w-full py-4 rounded-2xl bg-gray-900 text-white font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 transition disabled:opacity-50"
        >
          {saving ? "Saving…" : "Save personal information"}
        </button>
      </form>
    </div>
  );
}

